class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        char_groups = defaultdict(list)
        current_char = s[0]
        current_length = 1

        for char in s[1:]:
            if char == current_char:
                current_length += 1
            else:
                char_groups[current_char].append(current_length)
                current_char = char
                current_length = 1
        char_groups[current_char].append(current_length)

        max_len = -1
        for char in char_groups:
            lengths = sorted(char_groups[char], reverse=True)
            if len(lengths) >= 3:
                if lengths[2] > max_len:
                    max_len = lengths[2]
            if len(lengths) >= 2 and lengths[0] >= 2:
                if lengths[1] >= 1 and (lengths[0] - 2) > max_len:
                    max_len = lengths[0] - 2
            if len(lengths) >= 1 and lengths[0] >= 3:
                if (lengths[0] - 2) > max_len:
                    max_len = lengths[0] - 2

        return max_len if max_len != 0 else -1
```

